using Microsoft.EntityFrameworkCore;
using seed_a_backend.Api.Infrastructure;

namespace seed_a_backend.Tests;

public class SeedDataImporterTests : IAsyncLifetime
{
    private readonly SqlServerTestDatabase _database = new();

    public ValueTask InitializeAsync() => _database.InitializeAsync();

    public ValueTask DisposeAsync() => _database.DisposeAsync();

    private static string SeedFilePath()
    {
        var directory = new DirectoryInfo(AppContext.BaseDirectory);
        while (directory is not null && !File.Exists(Path.Combine(directory.FullName, "seed-a-backend.slnx")))
        {
            directory = directory.Parent;
        }

        if (directory is null)
        {
            throw new InvalidOperationException("Repository-Wurzel (seed-a-backend.slnx) wurde nicht gefunden.");
        }

        return Path.Combine(directory.FullName, "seed-a-backend.Api", "Data", "anfangsdatenbestand.json");
    }

    [Fact]
    public async Task ImportIfEmptyAsync_gegen_leere_DB_befuellt_alle_Tabellen_korrekt()
    {
        await using var db = _database.CreateContext();
        var importer = new SeedDataImporter(db);

        await importer.ImportIfEmptyAsync(SeedFilePath());

        Assert.Equal(2, await db.Venues.CountAsync());
        Assert.Equal(4, await db.Rooms.CountAsync());
        Assert.Equal(6, await db.Events.CountAsync());
        Assert.Equal(12, await db.PriceCategories.CountAsync());

        var kleinerSaal = await db.Rooms.SingleAsync(r => r.Name == "Kleiner Saal");
        Assert.Equal(new[] { "A", "B", "C", "D", "E", "F" }, kleinerSaal.RowLabels);
        Assert.Equal(10, kleinerSaal.ColumnCount);
        Assert.Equal(new[] { 6 }, kleinerSaal.AisleColumns);

        var studio = await db.Rooms.SingleAsync(r => r.Name == "Studio");
        Assert.Empty(studio.AisleColumns);

        var kammerkonzert = await db.Events.SingleAsync(e => e.Titel == "Kammerkonzert Frühling");
        var belegtePositionen = await db.BookingPositions
            .Where(bp => bp.EventId == kammerkonzert.Id)
            .OrderBy(bp => bp.RowLabel).ThenBy(bp => bp.ColumnNumber)
            .ToListAsync();

        Assert.Equal(3, belegtePositionen.Count);
        Assert.Collection(belegtePositionen,
            p => Assert.Equal(("B", 3), (p.RowLabel, p.ColumnNumber)),
            p => Assert.Equal(("B", 4), (p.RowLabel, p.ColumnNumber)),
            p => Assert.Equal(("C", 7), (p.RowLabel, p.ColumnNumber)));

        Assert.All(belegtePositionen, p =>
        {
            Assert.Null(p.BookingId);
            Assert.Null(p.PriceCategoryId);
            Assert.Null(p.CancelledAtUtc);
        });

        var sinfonisches = await db.Events.SingleAsync(e => e.Titel == "Sinfonisches Openair-Programm");
        var keinePositionen = await db.BookingPositions.Where(bp => bp.EventId == sinfonisches.Id).CountAsync();
        Assert.Equal(0, keinePositionen);
    }

    [Fact]
    public async Task ImportIfEmptyAsync_zweiter_Lauf_gegen_befuellte_DB_erzeugt_keine_Duplikate()
    {
        await using var db = _database.CreateContext();
        var importer = new SeedDataImporter(db);
        var seedFilePath = SeedFilePath();

        await importer.ImportIfEmptyAsync(seedFilePath);
        var venuesNachErstemLauf = await db.Venues.CountAsync();
        var eventsNachErstemLauf = await db.Events.CountAsync();
        var positionenNachErstemLauf = await db.BookingPositions.CountAsync();

        await importer.ImportIfEmptyAsync(seedFilePath);

        Assert.Equal(venuesNachErstemLauf, await db.Venues.CountAsync());
        Assert.Equal(eventsNachErstemLauf, await db.Events.CountAsync());
        Assert.Equal(positionenNachErstemLauf, await db.BookingPositions.CountAsync());
    }

    [Fact]
    public async Task Gefilterte_Unique_Constraint_verhindert_doppelte_aktive_Belegung_desselben_Sitzplatzes()
    {
        await using var db = _database.CreateContext();
        var importer = new SeedDataImporter(db);
        await importer.ImportIfEmptyAsync(SeedFilePath());

        var kammerkonzert = await db.Events.SingleAsync(e => e.Titel == "Kammerkonzert Frühling");

        db.BookingPositions.Add(new Api.Domain.BookingPosition
        {
            EventId = kammerkonzert.Id,
            RowLabel = "B",
            ColumnNumber = 3,
            BookingId = null,
            PriceCategoryId = null,
            CancelledAtUtc = null,
        });

        await Assert.ThrowsAsync<DbUpdateException>(() => db.SaveChangesAsync());
    }
}

